, 255, 255, 0.95);\r\n        cursor: pointer;\r\n        z-index: 3;\r\n        transition: background-color 0.2s, width 0.2s;\r\n\r\n        &:hover {\r\n          background-color: #fff;\r\n          width: 8px;\r\n        }\r\n\r\n        &::after {\r\n          content: attr(data-title);\r\n          position: absolute;\r\n          bottom: calc(100% + 10px);\r\n          left: 50%;\r\n          transform: translateX(-50%);\r\n          padding: 8px 14px;\r\n          background-color: rgba(0, 0, 0, 0.9);\r\n          color: #fff;\r\n          font-size: 16px;\r\n          font-weight: 500;\r\n          line-height: 1.4;\r\n          white-space: nowrap;\r\n          border-radius: 4px;\r\n          opacity: 0;\r\n          pointer-events: none;\r\n          transition: opacity 0.2s;\r\n          z-index: 10;\r\n        }\r\n\r\n        &::before {\r\n          content: '';\r\n          position: absolute;\r\n          bottom: calc(100% + 6px);\r\n          left: 50%;\r\n          transform: translateX(-50%);\r\n          border: 5px solid transparent;\r\n          border-top-color: rgba(0, 0, 0, 0.9);\r\n          opacity: 0;\r\n          pointer-events: none;\r\n          transition: opacity 0.2s;\r\n          z-index: 10;\r\n        }\r\n\r\n        &:hover::after,\r\n        &:hover::before {\r\n          opacity: 1;\r\n        }\r\n      }\r\n    }\r\n\r\n    //章节导航按钮\r\n    .vjs-chapters-button {\r\n      .vjs-menu {\r\n        .vjs-menu-content {\r\n          max-height: 300px;\r\n          overflow-y: auto;\r\n        }\r\n\r\n        .vjs-menu-item {\r\n          font-size: 1.4em;\r\n          padding: 0.5em 1em;\r\n\r\n          &:hover {\r\n            background-color: rgba(0, 0, 0, 0.3);\r\n          }\r\n\r\n          &.vjs-selected {\r\n            background-color: rgba(255, 255, 255, 0.3);\r\n          }\r\n        }\r\n      }\r\n    }\r\n\r\n    //缩略图样式\r\n    .vjs-mouse-display .vjs-time-tooltip {\r\n      display: flex !important;\r\n      