js-playback-rate.vjs-control{\r\n      width: 5.1em;\r\n\r\n      .vjs-menu-button {\r\n        padding: 0;\r\n      }\r\n    }\r\n\r\n    .vjs-menu li.vjs-menu-item{\r\n\r\n      &:hover {\r\n        background-color: rgba(0, 0, 0, 0.3);\r\n      }\r\n    }\r\n\r\n    .vjs-button > .vjs-icon-placeholder:before {\r\n      font-size: 2.8em;\r\n      line-height: 1.67;\r\n    }\r\n\r\n    .vjs-duration-display,\r\n    .video-js .vjs-playback-rate-value,\r\n    .vjs-current-time-display {\r\n      font-size: 2em;\r\n      line-height: 2.4em;\r\n    }\r\n\r\n    .vjs-menu-item {\r\n      font-size: 1.6em;\r\n      line-height: 1.8em;\r\n    }\r\n\r\n    .loading-spinner {\r\n      font-size: 20px;\r\n      width: 3em;\r\n      height: 3em;\r\n      border: 0.4em solid #f3f3f3;\r\n      border-top: 0.4em solid #54bbff;\r\n      border-radius: 50%;\r\n      animation: spin 1s linear infinite;\r\n    }\r\n\r\n    @keyframes spin {\r\n      0% {\r\n        transform: rotate(0deg);\r\n      }\r\n      100% {\r\n        transform: rotate(360deg);\r\n      }\r\n    }\r\n\r\n    .hash-error-mask {\r\n      box-sizing: border-box;\r\n      position: absolute;\r\n      top: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 100%;\r\n      z-index: 1;\r\n      background: rgba(0, 0, 0, 0.8);\r\n      background: linear-gradient(180deg, rgba(0, 0, 0, 0.8), rgba(255, 255, 255, 0));\r\n      overflow: auto;\r\n      padding: 20px 24px;\r\n      color: #fff;\r\n      margin: 0;\r\n      font-size: 14px;\r\n      line-height: 1.5;\r\n      text-align: center;\r\n    }\r\n\r\n    .custom-play-pause-btn{\r\n      opacity: 0;\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 50%;\r\n      width: 5em;\r\n      height: 5em;\r\n      transform: translate(-50%, -50%) scale(0.8);\r\n    }\r\n\r\n    .vjs-touch-enabled.vjs-waiting .vjs-custom-play-pause-button,\r\n    .vjs-waiting .vjs-custom-play-pause-button,\r\n    .vjs-custom-play-pause-button {\r\n      display: none;\r\n    }\r\n\r\n    .vjs-touch-enabled {\r\n      .vjs-custom-play-pause-button {\r\n        display: inline-block;\r\n      }\r\n    }\r\n  }\r\n\r\n  @media (max-width: 768px) {\r\n    .video-player-wrap {\r\n      .loading-spinner {\r\n        font-size: 12px;\r\n      }\r\n\r\n      .video-js {\r\n\r\n        &.vjs-playing {\r\n          .custom-play-pause-btn .vjs-icon-placeholder::before{\r\n            content: \"\\f103\";\r\n          }\r\n        }\r\n\r\n        &.vjs-paused {\r\n          .custom-play-pause-btn .vjs-icon-placeholder::before{\r\n            content: \"\\f101\";\r\n          }\r\n\r\n          .custom-play-pause-btn {\r\n            transform: translate(-50%, -50%) scale(0.9);\r\n          }\r\n        }\r\n      }\r\n\r\n      .vjs-has-started {\r\n        .custom-play-pause-btn{\r\n          opacity: 1;\r\n          position: absolute;\r\n          top: 50%;\r\n          left: 50%;\r\n          width: 5em;\r\n          height: 5em;\r\n          transform: translate(-50%, -50%) scale(0.8);\r\n          font-size: 1.6em;\r\n          background: rgba(0, 0, 0, 0.6);\r\n          border: 0px;\r\n          border-radius: 50%;\r\n          cursor: pointer;\r\n          margin: 0px;\r\n          padding: 0px;\r\n          pointer-events: auto;\r\n          outline: none;\r\n          transition: opacity 200ms ease 0s, transform 600ms ease 0s;\r\n          -webkit-tap-highlight-color: rgba(0, 0, 0, 0);\r\n        }\r\n\r\n        .custom-play-pause-btn .vjs-icon-placeholder {\r\n          position: relative;\r\n          width: 100%;\r\n          height: 100%;\r\n        }\r\n\r\n        .custom-play-pause-btn .vjs-icon-placeholder::before {\r\n          position: absolute;\r\n          top: 50%;\r\n          left: 50%;\r\n          height: auto;\r\n          transform: translate(-50%, -50%);\r\n        }\r\n\r\n      }\r\n      .vjs-user-inactive {\r\n        .custom-play-pause-btn {\r\n          opacity: 0;\r\n          visibility: visible;\r\n          pointer-events: none;\r\n          transition: visibility 1s, opacity 1s;\r\n        }\r\n\r\n        &.vjs-paused {\r\n          .custom-play-pause-btn {\r\n            opacity: 1;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n @media screen and (max-width: 1248px) {\r\n    .video-player-wrap {\r\n      .video-js .vjs-big-play-button{\r\n        width: 12.980769230769232vw;\r\n        height: 8.333333333333332vw;\r\n        font-size: 7.211538461538461vw;\r\n      }\r\n    }\r\n  }\r\n  @media screen and (max-width: 960px) {\r\n    .video-player-wrap {\r\n      .video-js .vjs-big-play-button{\r\n        width: 2.23em;\r\n        height: 1.43em;\r\n        font-size: 5.6em;\r\n      }\r\n    }\r\n  }\r\n  @media screen and (max-width: 640px) {\r\n    .video-player-wrap {\r\n      .video-js .vjs-big-play-button{\r\n        width: 19.53125vw;\r\n        height: 12.5vw;\r\n        font-size: 8.75vw;\r\n      }\r\n    }\r\n\r\n  }\r\n"],"sourceRoot":""}]);
